 notes.push({id,nominal:nom,at,offset,duration:dur,pitch,velocity,drumSource:source.id});
 }
}
lines.push(...overlays.map(o=>"OVERLAY "+JSON.stringify(o)));
store("notes",notes);store("desired",lines.join("\n"));text(notes);
